(538, NULL, 'TECHNIP', 'SKANDI BUZIOS TFMC', 'Aeroporto de Jacarepaguá ', '{"grupo":"TECHNIP","unidade":"SKANDI BUZIOS TFMC","data":"2026-07-02","local":"Aeroporto de Jacarepaguá ","modal":"Helicóptero","preposto":"Elisa Martins ","horarios":{"saida_hotel":[{"label1":"Previsto","h1":"5","m1":"00","label2":"Real","h2":"5","m2":"07"}],"embarque_previsto":"7:20","embarque_real":"7:43","atendimento_inicio":"5:00","atendimento_fim":"11:00"},"info_troca":"<div><br><\/div>Colaborador ELTON ALEXANDRIA&nbsp;<span style=\"font-size: 1rem; -webkit-tap-highlight-color: transparent; -webkit-text-size-adjust: 100%;\">BELARMINDO BARRETO retirado do voo devido ao excesso de peso na aeronave.&nbsp;<\/span>","pax_embarcando":"Technip:\n\n1. ADEMILSON ANTONIO PEREIRA CAUS\n2. CLAYTON BRITO PEREIRA\n3. JEFERSON LIMA BEU\n4. CLEITON DA SILVA\n5. FLAVIO MORAES BARBOSA\n6. MATHEUS OLIVEIRA GONZAGA DA SILVA\n7. VINICIUS ISIDORO ALVES ","pax_desembarcando":"Technip: \n\n1. CARLOS HENRIQUE DE OLIVEIRA CARNEIRO\n2. EDER SILVA SANTOS\n3. AYRTON DE ALMEIDA REZENDE\n4. ERIC DE CASTRO DOS SANTOS\n5. FABIO DE SOUZA LEANDRO\n6. FAGNER RODRIGUES DE SOUZA\n7. JOSE AUGUSTO DE CASTRO DOS SANTOS ","fotos":[]}', 0, NULL, '2026-07-02 21:09:19', '2026-07-10 10:05:16', 'TECHNIP', NULL, NULL, '2804:14d:5c8e:34f5:6c0b:a843:3d54:4b6');
